use crate::aap::caps::kb_read;

/// Bound on the question, measured both in characters and in bytes, so the
/// `ensures` holds whichever measure `len` is taken to mean.
const MAX_QUESTION: usize = 512;

/// The `requires` already guarantees the question is within bound; this is a
/// defensive pass-through that keeps the `ensures` true regardless.
fn bound_question(q: &str) -> String {
    let mut out = String::new();
    let mut chars = 0usize;
    for c in q.chars() {
        if chars + 1 > MAX_QUESTION || out.len() + c.len_utf8() > MAX_QUESTION {
            break;
        }
        out.push(c);
        chars += 1;
    }
    out
}

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(&query.query.question);

        let knowledge: Vec<String> = kb_read::lookup(&question);

        // `ensures present(knowledge)`: an empty result cannot satisfy the
        // contract, and inventing knowledge to fill it would be worse. Trap
        // at the boundary instead of emitting a non-conforming output.
        if knowledge.is_empty() {
            panic!("FetchContext: knowledge base returned no entries; output would violate ensures present(knowledge)");
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
