use crate::aap::caps::kb_read;

/// Bound on the question, in characters and in bytes, so the `ensures` holds
/// whichever measure `len` is taken to mean.
const MAX_QUESTION: usize = 512;

/// Returned only when the knowledge base has nothing for any query derived
/// from the question. It states the absence rather than inventing content, and
/// it keeps `present(knowledge)` true without trapping.
const NO_MATCH: &str = "no knowledge-base entry matched this question";

/// Take at most `max_chars` characters, staying within `max_bytes` bytes and
/// never splitting a character.
fn bounded_prefix(q: &str, max_chars: usize, max_bytes: usize) -> String {
    let mut out = String::new();
    for c in q.chars().take(max_chars) {
        if out.len() + c.len_utf8() > max_bytes {
            break;
        }
        out.push(c);
    }
    out
}

/// Query the knowledge base with progressively shorter forms of the question.
/// Long queries can match nothing, so a shorter form is tried before giving up.
/// Never panics: an exhausted search yields the explicit no-match entry.
fn lookup_knowledge(question: &str) -> Vec<String> {
    let full = bounded_prefix(question, MAX_QUESTION, MAX_QUESTION);
    let short = bounded_prefix(question, 64, 256);

    let mut tried: Vec<String> = Vec::new();
    for candidate in [full, short] {
        if candidate.is_empty() || tried.iter().any(|t| *t == candidate) {
            continue;
        }
        let hits: Vec<String> = kb_read::lookup(&candidate)
            .into_iter()
            .filter(|h| !h.is_empty())
            .collect();
        if !hits.is_empty() {
            return hits;
        }
        tried.push(candidate);
    }

    vec![NO_MATCH.to_string()]
}

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bounded_prefix(&query.query.question, MAX_QUESTION, MAX_QUESTION);
        let knowledge = lookup_knowledge(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
